/**
 * Link version 3, frozen: the shapes of the lifecycle channels (the installation scenario, the per-subject snapshot, the
 * capability catalogue, the effective projections and the control inbox's status).
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 3 was cut. It never
 * references the living types. Setting keys are frozen as text here: the closed list of settings is the registry in
 * `settingValues.ts`, and the capability catalogue grows with it. Do not edit this file to match a changed handler: a
 * change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/`. `tests/remote/contractV3.test.ts` checks the
 * living types against it.
 */

import type { ScenarioOverlayStatusV3 } from './shapesScenarios';

/** A failure answer: its reason, and the generation the facade says it is at when it does. */
export type LifecycleFailureV3 = { success: false; error: string; issues?: undefined; generation?: number };

export type InstallationExecutorV3 = 'electron' | 'cli' | 'web' | 'android-service' | 'android-app';

export type InstallationV3 = { scenario: string; executor: InstallationExecutorV3; generation: number };

/** One value a scenario reads: known, confirmed absent, or unknown. */
type ValueStateV3 =
    | { state: 'known'; value: ExprValueV3 }
    | { state: 'absent'; reason: 'not-applicable' | 'not-present' }
    | { state: 'unknown'; reason: string; dependencies: string[] };

type ExprValueV3 =
    | { kind: 'number'; value: number; quantity: string }
    | { kind: 'boolean'; value: boolean }
    | { kind: 'string'; value: string }
    | { kind: 'list'; value: string[] };

/** One installation setting as it applies now: its value and where it comes from, or why it cannot be read. */
export type EffectiveValueV3 =
    | { available: true; source: 'saved' | 'scenario'; value: ExprValueV3 }
    | { available: false; reason: string };

export type ScenarioCapabilityRowV3 = {
    key: string;
    disposition: string;
    read: 'value' | 'projection';
    phaseWrite: readonly ('challenge' | 'installation')[];
    owner: string;
    restriction?: string;
    value:
        | { kind: 'boolean' }
        | { kind: 'number'; quantity: 'duration'; unit: 'seconds' | 'minutes' | 'hours' }
        | { kind: 'number'; quantity: string }
        | { kind: 'string' }
        | { kind: 'enum'; values: readonly string[] }
        | { kind: 'list' }
        | { kind: 'other' };
};

/** One request as the control inbox reports it: never its arguments. */
export type ControlRecordV3 = {
    requestId: string;
    operation: string;
    target: string;
    status: 'pending' | 'applied' | 'failed' | 'superseded' | 'interrupted';
    error: string | null;
    revision: number;
    at: number;
};

type RowStateV3<Known extends object> =
    | ({ state: 'known' } & Known)
    | { state: 'absent'; reason: string }
    | { state: 'unknown'; reason: string };

type ResolvedSchedulesV3 = {
    submit?: { alignment: 'end' | 'absolute'; rows: ({ count: number } & RowStateV3<{ at: number }>)[] };
    vote?: { rows: RowStateV3<{ start: number; end: number }>[] };
    pause?: { rows: RowStateV3<{ start: number; end: number }>[] };
};

/** The body of `get-scenario-snapshot`: where one subject stands. */
export type SnapshotBodyV3 = {
    success: true;
    subject: string;
    assignment: string | InstallationV3 | null;
    corrupt: false | 'file' | 'record' | 'unloaded';
    paused: null | { at: number; reason: string };
    generation: number | null;
    withdrawn: boolean;
    base: { [key: string]: ValueStateV3 };
    effective: { [key: string]: ValueStateV3 };
    overlay: ScenarioOverlayStatusV3 | null;
    publication: { revision: number; observedAt: number; validUntil: number | null; profile: string | null } | null;
    schedules:
        | { kind: 'none' }
        | { kind: 'resolved'; schedules: ResolvedSchedulesV3 }
        | { kind: 'unavailable'; reason: string }
        | null;
    pins: {
        effective: { boost: null | string; turbo: null | string };
        stored: { boost: null | string; turbo: null | string };
    } | null;
    pool: {
        name: string;
        only: boolean;
        inOrder: boolean;
        ids: string[];
        block: 'pool-unbound' | 'pool-exhausted' | null;
    } | null;
};
